  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val Request_Qualification_governor_process_request_qualification_id = Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_request_qualification.id
    val Battery_Assessment_governor_process_battery_assessment_id = Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_battery_assessment.id
    val Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_id = Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_lifecycle_decision_owner.id
    val Controlled_Outcome_Derivation_governor_process_controlled_outcome_derivation_id = Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation.id
    val Attention_Derivation_governor_process_attention_derivation_id = Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_attention_derivation.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Request_Qualification_governor_process_request_qualification_id =>
          val prefix = "Request_Qualification_governor_process_request_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Drone_Lifecycle_Governor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Drone_Lifecycle_Governor
                |
                |import org.sireum._
                |import scp_candidate.Drone_Lifecycle_Governor._
                |
                |class ${suiteName} extends Request_Qualification_governor_process_request_qualification_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Battery_Assessment_governor_process_battery_assessment_id =>
          val prefix = "Battery_Assessment_governor_process_battery_assessment_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Drone_Lifecycle_Governor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Drone_Lifecycle_Governor
                |
                |import org.sireum._
                |import scp_candidate.Drone_Lifecycle_Governor._
                |
                |class ${suiteName} extends Battery_Assessment_governor_process_battery_assessment_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_id =>
          val prefix = "Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Drone_Lifecycle_Governor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Drone_Lifecycle_Governor
                |
                |import org.sireum._
                |import scp_candidate.Drone_Lifecycle_Governor._
                |
                |class ${suiteName} extends Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
