                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Controlled_Outcome_Derivation_governor_process_controlled_outcome_derivation_id =>
          val prefix = "Controlled_Outcome_Derivation_governor_process_controlled_outcome_derivation_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Drone_Lifecycle_Governor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Drone_Lifecycle_Governor
                |
